"""Base classes for gene prediction."""

from abc import ABC, abstractmethod
from dataclasses import dataclass
from pathlib import Path


@dataclass(frozen=True)
class GenePredictionResult:
    """Output files generated by a gene predictor."""

    input_fasta: Path
    output_dir: Path
    protein_fasta: Path
    nucleotide_fasta: Path
    gff_file: Path
    log_file: Path


class GenePredictor(ABC):
    """Abstract interface for gene prediction tools."""

    @abstractmethod
    def predict(
        self,
        genome_fasta: str | Path,
        output_dir: str | Path,
        prefix: str | None = None,
    ) -> GenePredictionResult:
        """Predict genes from a genome FASTA file."""
